<script setup>const email=ref('admin@alpha.test'),password=ref('Admin123!'),error=ref('');async function login(){error.value='';try{await $fetch('/api/auth/login',{method:'POST',body:{email:email.value,password:password.value}});await navigateTo('/')}catch(e){error.value=e.data?.statusMessage||'Login gagal'}}</script><template><main class="wrap"><form class="login" @submit.prevent="login"><h1>AppDesk</h1><p class="muted">Satu akun, semua aplikasi perusahaan.</p><label>Email</label><input v-model="email" class="field" type="email"><label>Password</label><input v-model="password" class="field" type="password"><p v-if="error" class="error">{{error}}</p><button class="btn" style="width:100%">Masuk</button></form></main></template>